    for (int i = 0; i < n; i++) dp[i][i] = basePairs[i];
    for (int i = 0; i < n - 1; i++) {
      for (int j = i + 1; j < n; j++) {
        if (basePairs[i] == basePairs[j]) {
          dp[i][j] = dp[i + 1][j - 1];
        } else {
          int minLen = dp[i][j - 1].length < dp[i + 1][j].length ? dp[i][j - 1].length : dp[i + 1][j].length;
          dp[i][j] = dp[i][j - 1].length == dp[i + 1][j].length ? '(': ')' : dp[i][j - 1].substring(0, minLen);
        }
      }
    }
    List<String> path = [];
    int i = 0;
    int j = n - 1;
    while (i <= j) {
      path.add(dp[i][j]);
      if (dp[i][j] == '(') {
        i++;
      } else if (dp[i][j] == ')') {
        j--;
      } else {
        i++;
        j--;
      }
    }
    return path.reversed.join('');
  }

  List<String> dnaStrings = ['ATCG', 'A', 'AT', 'ATCGT', 'ATCGAT', 'TCGA'];
  for (var dna in dnaStrings) {
