      return;
    }

    for (String edit in editsSet) {
      if (word.contains(edit)) {
        String substitute = word.substring(0, word.indexOf(edit)) + edit + word.substring(word.indexOf(edit) + 1);

        Map<String, int> subSubOccurrences = subOccurrences.map((key, value) => MapEntry(key, value * value));
        subSubOccurrences[substitute] = (subSubOccurrences[substitute] ?? 0) + 1;

        if (subSubOccurrences[substitute]! >= 2) {
          candidates.add(substitute);
        }
      }
    }
  }

  void backtrack(String word, int remainingLen) {
    if (remainingLen == 0) {
      return;
    }

    if (editsToSubstitutes.containsKey(word)) {
      List<String> subs = editsToSubstitutes[word]!;

      for (String sub in subs) {
        int subLen = sub.length;
        if (subLen <= remainingLen) {
          backtrack(sub, remainingLen - subLen);
        }
      }
    }

    search(word, remainingLen, validEdits, candidates);
  }

  List<String> possibleEdits = [];

  for (String word in edits) {
    int len = word.length;
    if (len <= targetLen) {
      Map<String, int> subOccurrences = {};
      backtrack(word, targetLen - len);

      for (String candidate in candidates) {
        subOccurrences[candidate] = (subOccurrences[candidate] ?? 0) + 1;
      }

      for (String candidate in candidates) {
        if (subOccurrences[candidate]! >= 2) {
          possibleEdits.add('$word -> $candidate');
        }
      }
      candidates = [];
    }
  }

  print(possibleEdits);
}

