Map<String, int> fn0(List<String> commands) {
  List<int> stack = [0];
  List<String> history = [];
  int total = 0;
  int high = 0;
  List<int> valid = [];

  for (String cmd in commands) {
    if (cmd == '^') {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else if (cmd == '<') {
      if (stack.length >= 2) {
        int a = stack.removeLast();
        int b = stack.removeLast();
        stack.add(b);
        stack.add(a);
      }
    } else if (cmd == '!') {
      int temp = stack.removeLast();
      history.add(temp);
      total += temp;
      high += temp * 2;
      valid.add(temp);
    } else if (cmd == '*') {
      int a = stack.removeLast();
      int b = stack.removeLast();
      stack.add(a * b);
    } else {
      int val = int.parse(cmd);
      stack.add(val);
      total += val;
      high += val;
      valid.add(val);
    }
  }

  List<int> reversed = List.of(valid)..reverse();
  int n = reversed.length;
  int k = n ~/ 2;

  while (k > 0) {
    for (int i = 0; i < k; i++) {
      if (reversed[i] >= 0) {
        for (int j = n - 1 - i; j >= k; j--) {
          if (reversed[j] >= 0) {
            int temp = reversed[i];
            reversed[i] = reversed[j];
            reversed[j] = temp;
            break;
          }
        }
      }
    }
    k ~/= 2;
  }

  List<int> indices = List.generate(n, (i) => i);
  indices.sort((a, b) {
    int cmp = reversed[a].compareTo(reversed[b]);
    if (cmp != 0) return cmp;
    return a.compareTo(b);
  });

  Map<String, int> result = {};
  result['total'] = total;
  result['high'] = high;
  result['valid'] = valid.length;
  result['indices'] = indices;

  return result;
}

