    shuffled[i] = shuffled[j];
    shuffled[j] = tmp;
  }

  print(shuffled);

  List<List<int>> windows = [];
  for (int i = 0; i < numbers.length; i++) {
    if (i % 3 == 2) {
      windows.add(numbers.sublist(i - 2, i + 1));
    }
  }

  print(windows);

  List<List<int>> zigzag = [];
  int direction = 1;
  for (int i = 0; i < numbers.length; i++) {
    int count = 0;
    bool inWindow = false;
    for (int j = 0; j < windows.length; j++) {
      if (i == windows[j].length) {
        inWindow = true;
        break;
      }
      if (windows[j].isNotEmpty && windows[j][count] == numbers[i]) {
        break;
      }
      count++;
    }
    if (inWindow) {
      zigzag.add(numbers.sublist(i - count, i + 1));
    } else {
      direction = -direction;
      if (direction == 1) {
        zigzag.add(numbers.sublist(i - 1, i + 1));
      }
    }
  }

  print(zigzag);

  List<int> spiral = [];
  int radius = 0;
  int minX = 0;
  int minY = 0;
  while (spiral.length < numbers.length) {
    for (int i = minX; i < minX + radius * 2 + 1; i++) {
      spiral.add(numbers[i + minY]);
    }
    minX += radius + 1;
    radius++;
    for (int i = minY + 1; i < minY + radius * 2 + 1; i++) {
      spiral.add(numbers[i + minX]);
    }
    minY += radius + 1;
    for (int i = minX + radius - 1; i >= minX; i--) {
      spiral.add(numbers[i + minY]);
    }
    if (minY > minY + radius - 1) {
      for (int i = minY - 1; i >= minY + 1; i--) {
        spiral.add(numbers[i + minX]);
      }
    }
  }

  print(spiral);
}

