    List<String>.generate(
      args.length,
      (i) => i == 0 ? '${args[i]}' : '${args[i-1]}_${args[i]}',
    ),
  );

  void backtrack(List<String> remaining, List<String> current, int index) {
    if (current.length == args.length) {
      print(current.join(' '));
      return;
    }

    for (int i = 0; i < remaining.length; i++) {
      if (remaining[i].isEmpty) continue;
      if (i > 0 && remaining[i] == remaining[i-1]) continue;
      if (remaining[i].length < current[index].length) {
        continue;
      }

      int minLen = remaining[i].length < current[index].length
          ? remaining[i].length
          : current[index].length;

      for (int j = 0; j < minLen; j++) {
        if (remaining[i][j] == current[index][j]) {
          List<String> next = List<String>.from(current);
          next.add(remaining[i]);
          backtrack(
            remaining.toList()..removeAt(i),
            next,
            index + 1,
          );
          break;
        }
      }
    }
  }

  List<String> firstPass = List<String>.generate(
    args.length,
    (i) => args[i],
  );
  backtrack(
    firstPass,
    [firstPass[0]],
    1,
  );
}

