void fn0(List<String> args) {

  int maxLen = args.length > 0
      ? args.fold(0, (int max, String arg) {
          int len = arg.length;
          if (len > max) return len;
          return max;
        })
      : 0;

  if (maxLen == 0) {
    print('No arguments provided. Exiting.');
    return;
  }

  int n = args.length;
  if (n == 1) {
    print('Single argument: "${args[0]}"');
    return;
  }

  List<String> allSubstrings = [];

  void backtrack(int start, int end, int length) {
    if (length == maxLen) {
      allSubstrings.add(args.join(','));
      return;
    }

    for (int i = start; i <= n - length; i++) {
      for (int j = i + 1; j <= n; j++) {
        if (args[i] == args[j] && i != j) {
          continue; 
        }

        String sub = args.sublist(i, j).join(' ');
        allSubstrings.add(sub);

        backtrack(j + 1, end, length + 1);
      }
    }
  }

  backtrack(0, n, 0);

  if (allSubstrings.isEmpty) {
    print('No substrings found.');
  } else {
    print('All substrings of ${args.join(", ")}:');
    for (String sub in allSubstrings) {
      print(sub);
