void fn0() {

  List<String> rows = [
    '...#...',
    '#...#...',
    '#.#####.',
    '#.#####.',
    '...#...',
  ];

  List<String> paths = [
    '.........',
    '.........',
    '.........',
    '.........',
    '.........',
  ];

  List<List<String>> grid = [
    for (var s in rows) s.split('')
  ];

  int maxLen = 0;
  List<String> bestPath = [];

  void dfs(int r, int c, int len, List<String> path) {
    if (len == maxLen) {
      bestPath = path;
      return;
    }

    List<List<bool>> visited = List.generate(
      grid.length,
      (_) => List.filled(grid[0].length, false),
    );

    List<List<int>> dir = [
      [-2, -1], [-2, 1], [-1, -2], [-1, 2],
      [1, -2], [1, 2], [2, -1], [2, 1],
    ];

    for (var d in dir) {
      int nr = r + d[0];
      int nc = c + d[1];

      if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
        if (!visited[nr][nc] && grid[nr][nc] == '#') {
          visited[nr][nc] = true;
          dfs(nr, nc, len + 1, path + grid[nr][nc]);
        }
      }
    }
  }

  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      if (grid[r][c] == '#' && !visited[r][c]) {
        visited[r][c] = true;
        dfs(r, c, 1, []);
      }
    }
  }

  print('The longest path is: ${bestPath.join()}');
}

