void fn0() {
  List<String> args = List<String>.from(
    (process.argv.length > 1)
        ? List<String>.from(process.argv.sublist(1))
        : <String>[];

  String parse(List<String> tokens) {
    String name = tokens[0];
    List<String> data = [];
    for (int i = 1; i < tokens.length; i++) {
      String token = tokens[i];
      if (token.isEmpty) continue;
      if (token == '[') data.add('[]');
      else if (token == ']') data.add(']');
      else data.add(token);
    }
    return name + '(' + data.join(', ') + ')';
  }

  List<String> result = [];
  void parseTree(String node) {
    if (node.isEmpty) return;
    if (node == '[') {
      parseTree('[]');
    } else if (node == ']') {
      parseTree(result.removeLast());
    } else {
      result.add(node);
    }
  }

  for (String token in args) {
    if (token.isEmpty) continue;
    String parsed = parse(token.split(' '));
    parseTree(parsed);
  }

  print(result.join(', '));
}

