  int cols = maze[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  List<List<String>> directions = [
    [0, 1],
    [0, -1],
    [1, 0],
    [-1, 0],
  ];

  String start = maze[0][0];
  String end = maze[rows - 1][cols - 1];

  dp[0][0] = 1;

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (maze[i][j] == '.' && dp[i][j] == 0) {
        for (List<int> dir in directions) {
          int ni = i + dir[0];
          int nj = j + dir[1];

          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
            dp[ni][nj] = dp[i][j] + 1;
          }
        }
      }
    }
  }

  int total = 0;
  List<String> path = [];

  int currRow = rows - 1;
  int currCol = cols - 1;

  while (path.isEmpty) {
    if (dp[currRow][currCol] == 0) {
      break;
    }

    Map<String, int> map = {};

    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        String cell = maze[r][c];
        if (cell == start && cell != '.') {
          continue;
        }
        if (cell == end && cell != '.') {
          continue;
        }
        if (cell == '#' || cell == '.' || c == 0 || r == 0 || r == rows - 1 || c == cols - 1) {
          continue;
        }

        if (cell != '#' && dp[r][c] > 0) {
          map[cell] = (map[cell] ?? 0) + 1;
        }
      }
    }

    List<String> keys = map.keys.toList();
    keys.sort();

    path.add(keys[0]);

    for (int k = 1; k < keys.length; k++) {
      if (map[keys[k]]! > map[keys[k - 1]]!) {
        path.add(keys[k]);
      }
    }
  }

  print(path);
  print('Total steps: ${dp[0][0]}');
}

