  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + weights[i] - threshold;
  }
  if (prefix[0] < 0) return false;
  int left = 0, right = n;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (prefix[mid] >= 0) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  int windowStart = left;
  int sum = 0;
  for (int right = windowStart; right <= n; right++) {
    sum += prefix[right];
    if (sum >= 0) return true;
  }
  return false;
}

