  bool isSafe(int r, int c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
    if (board[r][c] != 0) return false;
    return true;
  }

  bool queen(int r, int c) {
    for (int i = 0; i < r; i++) {
      int prevCol = board[i][c];
      if (prevCol != 0) return false;
    }
    int prevRow = board[r][c];
    for (int i = 0; i < c; i++) {
      int prev = board[i][c];
      if (prev != 0) return false;
    }
