      for (int j = 0; j < cols; j++) {
        if (isSafe(i, j)) {
          board[i][j] = r;
          if (queen(i, j)) {
            if (place(r + 1, 0)) return true;
            board[i][j] = 0;
          }
        }
      }
    }
    return false;
  }

  if (place(0, 0)) {

