int fn0(List<List<int>> grid) {
  if (grid.length < 2) return -1;
  int rows = grid.length;
  int cols = grid[0].length;
  if (cols < 2) return -1;
  int totalEdgeSum = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int left = grid[r][c - 1];
      int right = grid[r][c + 1];
      int top = grid[r - 1][c];
      int bottom = grid[r + 1][c];
      totalEdgeSum += left + right + top + bottom;
    }
  }
  int target = (rows * cols + 1) ~/ 2;
  int low = 0;
  int high = totalEdgeSum;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    int sum = 0;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (grid[r][c] <= mid) {
          sum += grid[r][c];
        }
      }
    }
    if (sum >= target) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  if (low == 0) return -1;
  int threshold = low;
  int aboveCount = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] > threshold) aboveCount++;
    }
  }
  return aboveCount;
}

