  }
}

class Area {
  double calc(List<Point> points) {
    double area = 0;
    for (int i = 0; i < points.length; i++) {
      int j = (i + 1) % points.length;
      area += points[i].x * points[j].y - points[j].x * points[i].y;
    }
    return area.abs() / 2;
  }
}

