Map<String, int> fn0(List<String> phases, List<int> durations) {
  final List<MapEntry<String, int>> queue = [];
  int cycleSum = 0;
  for (int i = 0; i < phases.length; i++) {
    final String p = phases[i];
    final int d = durations[i];
    if (p == 'green') {
      cycleSum += d;
      queue.add(MapEntry(p, d));
    } else if (p == 'red') {
      while (queue.isNotEmpty && queue.last.key == 'green') {
        cycleSum -= queue.removeLast().value;
      }
    } else if (p == 'yellow') {
      while (queue.isNotEmpty && queue.last.key == 'green') {
        cycleSum -= queue.removeLast().value;
      }
      queue.add(MapEntry(p, d));
    } else if (p == 'arrow') {
      while (queue.isNotEmpty && queue.last.key == 'green') {
        cycleSum -= queue.removeLast().value;
      }
      if (queue.isNotEmpty) {
        final MapEntry<String, int> top = queue.removeAt(0);
        queue.add(MapEntry(top.key, top.value + d));
      }
    }
  }
  return {'cycleSum': cycleSum, 'queueLen': queue.length};
}

