void fn0(List<String> args) {

  int n = args.isNotEmpty ? int.parse(args[0]) : 5;

  List<List<int>> pascal(int n) {
    List<List<int>> result = List.generate(n, (_) => List<int>.filled(n, 0));
    result[0][0] = 1;

    for (int i = 1; i < n; i++) {
      for (int j = 0; j <= i; j++) {
        if (j == 0 || j == i) {
          result[i][j] = 1;
        } else {
          int sum = 0;
          if (j - 1 >= 0) sum += result[i - 1][j - 1];
          if (j + 1 < i) sum += result[i - 1][j + 1];
          result[i][j] = sum;
        }
      }
    }
    return result;
  }

  void printPascal(int n) {
    List<List<int>> triangle = pascal(n);
    for (int i = 0; i < n; i++) {
      String row = '';
      for (int j = 0; j <= i; j++) {
        row += triangle[i][j].toString() + ' ';
      }
      print(row);
    }
  }

  print('Pascal Triangle:');
  printPascal(n);
}

