void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart fn0.dart <amount> [base] [coin] [flag]');
    print('  <amount>: Decimal amount to convert');
    print('  [base]: Optional base for fractional parts (default: 100)');
    print('  [coin]: Optional coin name for display (default: "cents")');
    print('  [flag]: Optional rounding flag (default: "round")');
    return;
  }

  final amount = int.tryParse(args[0]) ?? 0;
  final base = args.length > 1 ? int.tryParse(args[1]) ?? 100 : 100;
  final coin = args.length > 2 ? args[2] : "cents";
  final round = args.length > 3 ? args[3] : "round";

  final Map<String, int> cache = <String, int>{};
  int toInt(String s) => int.tryParse(s) ?? 0;

  int _parse(int amount, int base, String coin, String round) {
    if (base < 2 || base > 36) return 0;
    if (coin.isEmpty) coin = "cents";
    if (round.isEmpty) round = "round";

    String key = '$base-$coin-$round';
    if (cache.containsKey(key)) return cache[key]!;
    if (amount == 0) {
      cache[key] = 0;
      return 0;
    }

    int remainder = amount % base;
    int rounded = remainder < 0 ? base - remainder : remainder;

    int factor = 1;
    if (base > 100) {
      factor = base ~/ 100;
      rounded = rounded + (rounded > 0 ? 1 : -1);
    }

    int cents = rounded * factor;
    int dollars = cents ~/ 100;
    int remain = cents % 100;

    int frac = 0;
    if (remain == 0) {
      cache[key] = dollars;
      return dollars;
    }

    frac = rounded - dollars;
    int fracFactor = 1;
    if (frac < 0) {
      fracFactor = -1;
      rounded = base - rounded;
    }

    int fracCents = rounded * factor;
    int fracDollars = fracCents ~/ 100;
    int fracRemain = fracCents % 100;

    int dollarsRounded = (fracDollars + (frac == 0 ? 1 : -1)) * factor;
    int centsRounded = rounded + (frac >= 0 ? 1 : -1) * factor;

    cache[key] = dollarsRounded + (frac < 0 ? centsRounded : -centsRounded);
    return cache[key]!;
  }

  int result = _parse(amount, base, coin, round);
  print('$amount → ${toInt(result)} $coin');
}

