    int result = 1;
    while (n > 0) {
      result *= n;
      n--;
    }
    return result;
  }

  int binomialCoefficient(int n, int k) {
    if (k < 0 || k > n) return 0;
    int top = factorial(n);
    int bottom = factorial(k) * factorial(n - k);
    return top ~/ bottom;
  }

  int choose(int n, int k) {
    return binomialCoefficient(n, k);
  }

  void printWithPrefix(String text, int indent) {
    for (int i = 0; i < indent; i++) print(' ');
    print(text);
  }

  printWithPrefix('Factorials:');
  for (int i = 0; i <= 5; i++) {
    print('  $i! = ${factorial(i)}');
  }

  printWithPrefix('Binomial Coefficients:');
  for (int i = 0; i <= 5; i++) {
    for (int j = 0; j <= i; j++) {
      int value = choose(i, j);
      if (value > 0) {
        print('  ${i}C${j} = $value');
      }
    }
  }
}

