void fn0() {

  const Map<String, List<int>> parsed = {
    'A': [1, 2],
    'B': [3, 4],
    'C': [5, 6],
    'D': [7, 8],
    'E': [9, 10],
  };

  const Map<String, Map<String, int>> groupOrder = {
    'A': {'B': 1, 'C': 2},
    'B': {'D': 3, 'E': 4},
  };

  final Map<String, int> parent = {};
  final Map<String, int> rank = {};

  void find(String node) {
    if (node.isEmpty) return;
    if (node == '.') {
      parent[node] = 0;
      rank[node] = 0;
    } else if (parsed.containsKey(node)) {
      final List<int> weights = parsed[node]!;
      parent[node] = weights[0];
      rank[node] = weights[1];
      for (final String sibling in parsed.keys) {
        if (sibling != node) {
          find(sibling);
          if (rank[sibling]! >= rank[node]!) {
            final String tmp = node;
            node = sibling;
            sibling = tmp;
          }
        }
      }
    } else if (groupOrder.containsKey(node)) {
      final Map<String, int> subgroup = groupOrder[node]!;
      for (final String subgroupNode in subgroup.keys) {
        final int subgroupRank = subgroup[subgroupNode]!;
        if (subgroupRank > rank[node]!) {
          parent[node] = subgroupNode;
          rank[node] = subgroupRank;
        }
      }
    }
  }

  find('.');

  void dfs(String node, StringBuffer sb) {
    if (node.isEmpty) return;
    if (node == '.') {
      sb.write('0.');
    } else if (parsed.containsKey(node)) {
      final List<int> weights = parsed[node]!;
      sb.write('$node:${weights[0]},${weights[1]}');
    } else if (groupOrder.containsKey(node)) {
      final Map<String, int> subgroup = groupOrder[node]!;
      for (final String subgroupNode in subgroup.keys) {
        final int subgroupRank = subgroup[subgroupNode]!;
        if (subgroupRank > rank[node]!) {
          dfs(subgroupNode, sb);
        }
      }
    }
  }

  final StringBuffer sb = StringBuffer();
  dfs('.');
  print(sb.toString());
}

