      int left = solve(rest);
      if (left == val) {
        search(letter + rest, depth + 1, sb);
      }
    }
  }

  int val = solve(args[0]);
  StringBuffer sb = StringBuffer();
  search(args[0], 0, sb);
  print(sb.toString());
}

