void fn0() {

  const int row = 4;
  const int col = 5;

  const int wallMask = 0xF; 
  const int pathMask = 0x0F; 
  const int emptyMask = 0x00; 

  const int startRow = 0;
  const int startCol = 0;

  const int destRow = 3;
  const int destCol = 4;

  const int directionCount = 4;
  const int up = 0;
  const int right = 1;
  const int down = 2;
  const int left = 3;

  const int wallCode = 1;
  const int pathCode = 2;

  int width = col + 2 * directionCount; 
  int height = row + 2 * directionCount; 

  List<List<int>> map = List.generate(height, (_) => List.filled(width, 0));

  void printMap() {
    for (int i = 0; i < height; i++) {
      String rowStr = '';
      for (int j = 0; j < width; j++) {
        if (map[i][j] == wallCode) {
          rowStr += '#';
        } else if (map[i][j] == pathCode) {
          rowStr += ' ';
        }
      }
      print(rowStr.padRight(width, ' '));
    }
    print('');
  }

  int getDistance(int r1, int c1, int r2, int c2) {
    int dist = (r2 - r1).abs() + (c2 - c1).abs();
    return dist;
  }

  int heuristic(int r1, int c1, int r2, int c2) {
    int d1 = getDistance(r1, c1, startRow, startCol);
    int d2 = getDistance(r2, c2, destRow, destCol);
    return d1 + d2;
  }

  void setWalls() {
    for (int i = 0; i < height; i++) {
      for (int j = 0; j < width; j++) {
        if (i == 0 || i == height - 1 || j == 0 || j == width - 1) {
          map[i][j] = wallCode;
        }
      }
    }
  }

  void setStart() {
    map[startRow][startCol] = pathCode;
  }

  void setDest() {
    map[destRow][destCol] = pathCode;
  }

  void openPath(int r, int c) {
    for (int d = 0; d < directionCount; d++) {
      int nr = r + direction[d][0];
      int nc = c + direction[d][1];
      if (nr >= 0 && nr < height && nc >= 0 && nc < width && map[nr][nc] == wallCode) {
        map[r][c] |= 1 << d;
      }
    }
  }

  Map<String, List<int>> dijkstra(int startR, int startC, int destR, int destC) {
    Map<String, List<int>> dist = {};
    Map<String, Set<int>> prev = {};

    for (int r = 0; r < height; r++) {
      for (int c = 0; c < width; c++) {
        if (map[r][c] == pathCode) {
          dist["${r},${c}"] = [999999, -1];
        }
      }
    }

    dist["${startR},${startC}"] = [0, -1];
    prev["${startR},${startC}"] = {};

    for (int step = 0; step < height * width; step++) {
      int minDist = 999999;
      int? prevCell;

      for (String key in dist.keys) {
        List<int> cell = dist[key]!;
        if (cell[0] < minDist) {
          minDist = cell[0];
          prevCell = key;
        }
      }

      if (prevCell == null) break;

      String cellKey = prevCell!;
      List<int> cell = dist[cellKey]!;

      int r = cell[0];
      int c = cell[1];

      if (r == destRow && c == destCol) break;

      for (int d = 0; d < directionCount; d++) {
        int nr = r + direction[d][0];
        int nc = c + direction[d][1];
        if (nr >= 0 && nr < height && nc >= 0 && nc < width && map[nr][nc] == wallCode) {
          continue;
        }

        int nd = (1 << d) & wallMask;
        int newMask = cell[2] & nd;

        if (newMask == 0) {
          continue;
        }

        int updated = cell[0] + (1 << d) + heuristic(r, c, destRow, destCol);

        if (!prev.containsKey("${nr},${nc}")) {
          prev["${nr},${nc}"] = {};
        }

        String key = "${nr},${nc}";
        if (dist[key]! != [999999, -1]) {
          if (dist[key]![0] < updated) continue;
        }

        dist[key] = [updated, d];

        openPath(nr, nc);
      }

      if (prevCell != null) {
        String cellKey = prevCell!;
        List<int> cell = dist[cellKey]!;
        int r = cell[0];
        int c = cell[1];
        String id = "($r,$c)";
        print(id);
        printMap();
      }
    }
  }

  setWalls();
  setStart();
  setDest();
  printMap();

  dijkstra(startRow, startCol, destRow, destCol);
}

