void fn0() {




  final Set<String> stops = {
    'A',
    'B',
    'C',
    'D',
    'E',
    'F'
  };
  final Map<String, List<String>> routes = {
    'A': ['B', 'C'],
    'B': ['D', 'E'],
    'C': ['E', 'F'],
    'D': ['F'],
    'E': [],
    'F': []
  };

  final Map<String, int> departureTimes = {
    'A': 7,
    'B': 10,
    'C': 15,
    'D': 20,
    'E': 25,
    'F': 30
  };

  const List<String> validStops = ['A', 'B', 'C', 'D', 'E', 'F'];

  final Map<String, String> currentRoute = {};
  final Set<String> validRoutes = {};

  for (final entry in routes.entries) {
    if (!stops.contains(entry.key)) continue;
    if (!validRoutes.contains(entry.value.join())) {
      validRoutes.add(entry.value.join());
    }
  }

  for (final stop in validStops) {
    final List<String> path = [];
    final Set<String> visited = {};
    final List<String> routesVisited = [];

    void dfs(String node) {
      if (node == stop) {
        path.add(node);
        return;
      }
      if (!routes.containsKey(node)) return;
      visited.add(node);

      final List<String> children = routes[node]!;
      for (final child in children) {
        if (!visited.contains(child)) {
          dfs(child);
          routesVisited.add(child);
        }
      }
    }

    dfs(stop);
    final String route = routesVisited.join(' -> ');
    final int time = departureTimes[stop]!;
    print('$stop: $route, $time');
  }

  final List<String> sortedRoutes = validRoutes.toList()..sort();
  print('Valid routes: $sortedRoutes');
}

