  bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
      if (n % i == 0) return false;
    }
    return true;
  }

  bool isPalindrome(int n) {
    int original = n;
    int reversed = 0;
    while (n > 0) {
      reversed = reversed * 10 + n % 10;
      n ~/= 10;
    }
    return original == reversed;
  }

