void fn0(List<String> args) {
  List<int> seeds = args.isNotEmpty
      ? args.map(int.parse).toList()
      : [1, 2, 3, 4, 5, 6, 7];

  int n = seeds.length;
  List<List<int>> dp = List.generate(n, (_) => List.filled(n, 0));

  for (int size = 2; size <= n; size++) {
    for (int i = 0; i <= n - size; i++) {
      int j = i + size - 1;
      int score = 0;
      bool roundRobin = true;
      for (int k = i; k < j; k++) {
        if (seeds[k] < seeds[i] || seeds[k] < seeds[j]) {
          score -= 1;
          roundRobin = false;
        } else if (seeds[k] > seeds[i] && seeds[k] > seeds[j]) {
          score += 2;
        } else {
          score += 1;
        }
      }
      if (roundRobin) {
        score += size;
      }
      dp[i][j] = score;
    }
  }

  List<List<String>> brackets = [];
  List<int> availableSeeds = List.generate(n, (i) => seeds[i]);
  bool paired = false;

  while (!paired) {
    paired = true;

    List<List<String>> nextBrackets = [];
    for (int i = 0; i < availableSeeds.length; i++) {
      for (int j = i + 1; j < availableSeeds.length; j++) {
        if (dp[i][j] >= 0) {
          nextBrackets.add([availableSeeds[i], availableSeeds[j]]);
        }
      }
    }

    brackets = nextBrackets;
    availableSeeds = [];
    for (var bracket in brackets) {
      if (availableSeeds.isEmpty || availableSeeds.last != bracket[0]) {
        availableSeeds.add(bracket[0]);
      }
    }
  }

  for (int i = 0; i < brackets.length; i++) {
    String outcome = dp[i[0] - 1][i[1] - 1] > 0
        ? '${brackets[i][0]} vs ${brackets[i][1]}'
        : '${brackets[i][0]} defeated ${brackets[i][1]}';
    print('${i + 1}.${outcome}');
  }
}

