Map<String, int> fn0(List<String> edits) {
  if (edits.isEmpty) return {'<new>': 0, '<del>': 0};
  int insertCount = 0;
  int deleteCount = 0;
  List<String> tokens = [];
  for (String edit in edits) {
    if (edit.isEmpty) {
      tokens.add('<new>');
      insertCount++;
    } else {
      String op = edit[0];
      if (op == '<') {
        String t = edit.substring(1);
        if (t == '<del>') {
          deleteCount++;
        } else {
          tokens.add(t);
          insertCount++;
        }
      } else if (op == '>') {
        int i = 0;
        while (i < tokens.length && tokens[i] != '<new>') {
          i++;
        }
        if (i < tokens.length) {
          String t = tokens[i];
          tokens.removeLast();
          insertCount--;
          if (t == '<del>') {
            deleteCount--;
          }
        }
      } else {
        tokens.add(op);
        insertCount++;
      }
    }
  }
  return {'<new>': insertCount, '<del>': deleteCount};
}

