  const Line.originToEuclidean(Point p)
      : this(Point.origin, p, distance: EuclideanMetric());

  const Line.random(Random rand)
      : this(Point.origin, Point(rand.nextDouble() * 2 - 1, rand.nextDouble() * 2 - 1));

  const Line.random(Random rand, double minX, double maxX, double minY, double maxY)
      : this(Point(rand.nextDouble() * 2 - 1, rand.nextDouble() * 2 - 1),
            Point(minX, maxX, minY, maxY));

  @override
  String toString() {
    if (a == b) return a.toString();
    return '${a} - ${b}';
  }

  double distance(Point p) {
    final dist = distanceFunc(a, p) + distanceFunc(b, p);
    return dist > dist(a, b) ? dist : dist(a, b);
  }

  double distanceFunc(Point a, Point b) {
    final dx = (a.x - b.x).abs();
    final dy = (a.y - b.y).abs();
    return distanceFunc(dx, dy);
  }

  double distanceFunc(double x, double y) {
    if (x < y) return x;
    return y;
  }
}

