  int green = (rgb >> 8) & 0xFF;
  int blue = rgb & 0xFF;
  int dominant;
  if (red >= green && red >= blue) {
    dominant = red;
  } else if (green >= red && green >= blue) {
    dominant = green;
  } else {
    dominant = blue;
  }
  int diff = dominant ^ (255 - dominant);
  return (diff + 1) / 2.0;
}

