double fn0(int packed) {
  int rows = packed >> 16;
  int cols = (packed & 0xFF) >> 8;
  int blocks = rows * cols;
  int edges = 0;
  for (int i = 0; i < blocks; i++) {
    int bit = (i >> 1) & 0x1F;
    int bits = 0;
    int temp = i;
    while (temp != 0) {
      bits += temp & 1;
      temp >>= 1;
    }
    if (bits == 0) edges++;
  }
  return edges / blocks;
}

