  if (days.isEmpty) return "";
  int left = 0;
  int right = days.length - 1;
  int result = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (days[mid] - days[0] <= targetGap) {
      result = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  if (result == -1) return "";
