@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final rand = Random(0);

  final int rows = 20;
  final int cols = 20;

  const int dirs = 8;
  const int maxIterations = 1000000;

  final List<List<int>> board = List.generate(rows, (_) => List.filled(cols, 0));

  void place(int r, int c) {
    if (board[r][c] == 1) return;
    board[r][c] = 1;
    place(r + 1, c);
    place(r - 1, c);
    place(r, c + 1);
    place(r, c - 1);
  }

  void generate() {
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (board[r][c] == 1) continue;
        bool isolated = true;

        final List<List<int>> queue = [
          [r, c]
        ];

        bool hasNeighbor = false;
        final List<int> neighbors = [

          [r + 1, c],
          [r - 1, c],
          [r, c + 1],
          [r, c - 1]
        ];

        while (queue.isNotEmpty) {
          final List<int> cell = queue.removeAt(0);
          final int cr = cell[0];
          final int cc = cell[1];

          for (final int d = 0; d < dirs; d++) {
            final int nr = cr + dirs[d];
            final int nc = cc + dirs[d];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] == 0) {
              final bool first = neighbors[d][0] == nr && neighbors[d][1] == nc;
              if (first) {
                hasNeighbor = true;
                break;
              }
              queue.add([nr, nc]);
            }
          }
        }

        board[r][c] = hasNeighbor && !isolated ? 1 : 0;
      }
    }
  }

  for (int iter = 0; iter < maxIterations; iter++) {
    final int r = rand.nextInt(rows);
    final int c = rand.nextInt(cols);
    place(r, c);
  }

  final List<List<int>> visited = List.generate(rows, (_) => List.filled(cols, 0));
  final List<List<int>> floodFill(List<List<int>> board, int r, int c) {
    if (board[r][c] == 1) return [];
    final List<List<int>> result = [
      [r, c]
    ];
    visited[r][c] = 1;
    final List<List<int>> neighbors = [

      [r + 1, c],
      [r - 1, c],
      [r, c + 1],
      [r, c - 1]
    ];

    for (final int d = 0; d < neighbors.length; d++) {
      final int nr = neighbors[d][0];
      final int nc = neighbors[d][1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && visited[nr][nc] == 0) {
        final List<List<int>> sub = floodFill(board, nr, nc);
        for (final int s = 0; s < sub.length; s++) {
          result.add(sub[s]);
        }
      }
    }
    return result;
  }

  final List<List<int>> zones = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (board[r][c] == 1) continue;
      if (visited[r][c] == 1) continue;
      final List<List<int>> connected = floodFill(board, r, c);
      if (connected.isEmpty) continue;
      zones.add(connected);
    }
  }

  print(zones);
}

