  const int rows = 20;
  const int cols = 20;

  final board = List.generate(rows, (_) => List.filled(cols, 0));
  const int width = cols;

  bool isSafe(int r, int c, int w) {
    for (int i = 0; i < w; i++) {
      int nr = r + i;
      int nc = c + i;
      if (nr >= rows || nc >= cols || nr < 0 || nc < 0) {
        return false;
      }
      if (board[nr][nc] == 1) {
        return false;
      }
    }
    return true;
  }

  bool solve(int r, int c, int w) {
    if (r == rows && c == cols) {
      return true;
    }
    if (c >= width || r >= width) {
      return false;
    }
    if (w == 0) {
      return isSafe(r, c, w) ? true : false;
    }

    for (int i = 0; i < width; i++) {
      if (isSafe(r, c + i, w - 1)) {
        board[r][c + i] = 1;
        if (solve(r + 1, c, w - 1)) {
          return true;
        }
        board[r][c + i] = 0;
      }
    }
    return false;
  }

  if (solve(0, 0, width)) {
    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        print(board[i][j]);
      }
