class BinarySearchTree<T> {
  final TreeNode root;

  BinarySearchTree(this.root);

  void insert(T value) {
    TreeNode? current = root;
    TreeNode? parent;
    while (current != null) {
      parent = current;
      if (value.compareTo(current.value) < 0) {
        current = current.left;
      } else {
        current = current.right;
      }
    }
    current = TreeNode(value, [TreeNode(value[0], [TreeNode(value[1])]), TreeNode(value[2])]);
    if (parent == null) {
      root = current;
    } else if (value.compareTo(parent.value) < 0) {
      parent.left = current;
    } else {
      parent.right = current;
    }
  }

  bool contains(T value) {
    TreeNode? current = root;
    while (current != null) {
      if (value.compareTo(current.value) < 0) {
        current = current.left;
      } else if (value.compareTo(current.value) > 0) {
        current = current.right;
      } else {
        return true;
      }
    }
    return false;
  }

  void printInorder(void Function(T) callback) {
    void _inorder(TreeNode? node) {
      if (node == null) return;
      _inorder(node.left);
      callback(node.value);
      _inorder(node.right);
    }
    _inorder(root);
  }
}

