List<int> fn0(List<List<int>> grid, int threshold) {
  if (grid.isEmpty || grid[0].isEmpty) return [];
  final rows = grid.length;
  final cols = grid[0].length;
  List<int> result = [];
  Map<int, int> rowMax = {};
  for (int r = 0; r < rows; r++) {
    int bestVal = grid[r].reduce((a, b) => a > b ? a : b);
    rowMax[r] = bestVal;
    if (rowMax[r]! >= threshold) {
      List<int> run = [r];
      for (int c = r; c < cols; c++) {
        if (grid[r][c] >= threshold) {
          run.add(c);
        }
      }
      result.add(run.length);
    }
  }
  return result;
}

